    const st2 = E('button', 'btn-primary sd-q-paste', '② Dán bản chép lời & tạo câu'); st2.type = 'button';
    quick.appendChild(st1); quick.appendChild(st2);
    add.appendChild(quick);
    const how = E('details', 'sd-q-how');
