  // bản chép lời có vẻ là tiếng Việt (ví dụ YouTube đang dịch tự động) → báo để chọn lại English
  const subsLooksVi = r => { const t = r.s.map(x => x[0]).join(' '); const n = (t.match(/[ăâđêôơưạảấầẩẫậắằẳẵặẹẻẽếềểễệỉịọỏốồổỗộớờởỡợụủứừửữựỳỵỷỹáàãéèíìóòõúùý]/gi) || []).length; return n > Math.max(8, t.length * 0.03); };
  const SUBS_VI_MSG = 'Bản chép lời này có vẻ là tiếng Việt. Trên YouTube, ở khung “Bản chép lời” hãy chọn ngôn ngữ English (không chọn bản dịch tự động) rồi sao chép lại.';
  function ytParse(raw) {
    if (typeof lsParseTimed !== 'function') return null;
    const segs = lsParseTimed(raw || '');
    if (!segs) return null;
    const g = lsGroupSegments(segs).filter(x => x.en && x.end > x.start);
    if (!g.length) return null;
    return { s: g.map(x => [x.en, '']), tm: g.map(x => [x.start, x.end]) };
  }

