      if (clean(t)) { w.setAttribute('role', 'button'); w.tabIndex = 0; w.addEventListener('click', () => openWord(t)); w.addEventListener('keydown', e => { if (e.key === 'Enter') openWord(t); }); }
      box.appendChild(w);
