    const wrap = E('div', 'sd-chips-w');
    wrap.appendChild(E('div', 'sd-chips-t', res ? 'Kết quả từng từ (chạm từ đỏ để nghe riêng)' : 'Nghe và lặp lại câu trên'));
    const row = E('div', 'sd-wchips');
    T.toks.forEach((t, k) => {
      const ok = res ? res.ok[k] : null;
      const c = E('button', 'sd-wchip' + (ok === true ? ' ok' : ok === false ? ' bad' : ''), ok === null ? t.replace(/[A-Za-z0-9’']/g, '•') : t);
      if (ok !== null) c.addEventListener('click', () => speak(clean(t) || t, 0.75));
      row.appendChild(c);
    });
    wrap.appendChild(row);
    return wrap;
